'use strict';
const C=window.KITEEZI_CONFIG||{}, URL=String(C.SUPABASE_URL||'').replace(/\/+$/,''), KEY=String(C.SUPABASE_ANON_KEY||'');
let session=null,profile=null,tab='dashboard';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('en-UG').format(Number(v)||0);
async function api(path,opt={},token=session?.access_token||KEY){const h={apikey:KEY,Authorization:'Bearer '+token,'Content-Type':'application/json',...(opt.headers||{})};if(opt.method&&opt.method!=='GET')h.Prefer='return=representation';const r=await fetch(URL+path,{...opt,headers:h});const t=await r.text();let d;try{d=t?JSON.parse(t):null}catch{d=t}if(!r.ok)throw Error(d?.message||d?.msg||d?.error_description||d?.error||(typeof d==='string'?d:'Request failed'));return d}
function msg(e){console.error(e);alert(e.message||'Something went wrong.')}
async function login(e){
  if(window.__KITEEZI_ADMIN_LOGIN_BOUND__)return;
  e.preventDefault();
  const f=new FormData(e.currentTarget);
  const email=String(f.get('email')||'').trim();
  const password=String(f.get('password')||'');
  const statusEl=$('#loginMsg');
  const submitBtn=e.currentTarget.querySelector('button[type="submit"]');
  statusEl.hidden=false;
  statusEl.textContent='Signing in…';
  if(submitBtn) submitBtn.disabled=true;
  try{
    if(!URL||!KEY) throw Error('Admin configuration is missing.');
    const response=await fetch(URL+'/auth/v1/token?grant_type=password',{
      method:'POST',
      headers:{apikey:KEY,'Content-Type':'application/json'},
      body:JSON.stringify({email,password})
    });
    const raw=await response.text();
    let data=null; try{data=raw?JSON.parse(raw):null}catch{}
    if(!response.ok) throw Error(data?.msg||data?.message||data?.error_description||'Invalid email or password.');
    if(!data?.access_token||!data?.user?.id) throw Error('Login succeeded but no valid session was returned.');
    session=data;
    const p=await api('/rest/v1/profiles?select=*&id=eq.'+encodeURIComponent(session.user.id)+'&limit=1');
    profile=p?.[0];
    if(!profile) throw Error('This account has no Kiteezi staff profile.');
    if(!profile.active) throw Error('This Kiteezi staff profile is inactive.');
    sessionStorage.setItem('kiteezi_admin_session',JSON.stringify(session));
    show();
  }catch(err){
    session=null; profile=null;
    statusEl.textContent=err?.message||'Sign in failed. Please try again.';
    statusEl.hidden=false;
  } finally {
    if(submitBtn) submitBtn.disabled=false;
  }
}
async function restore(){try{session=JSON.parse(sessionStorage.getItem('kiteezi_admin_session')||'null');if(!session?.access_token)throw Error();const p=await api('/rest/v1/profiles?select=*&id=eq.'+encodeURIComponent(session.user.id)+'&limit=1');profile=p?.[0];if(!profile?.active)throw Error();show()}catch{session=null;$('#loginView').classList.remove('hide')}}
async function loadAdminLogo(){try{const r=await api('/rest/v1/site_settings?select=value&key=eq.logo_url&limit=1');const v=r?.[0]?.value||'';document.querySelectorAll('.brand-mark').forEach(el=>{if(!v){el.textContent='K';return;}const img=document.createElement('img');img.src=v.startsWith('http')?v:'../'+v.replace(/^\/+/, '');img.alt='Kiteezi Recreational Center';img.loading='eager';el.textContent='';el.appendChild(img);});const p=$('#logoPreview');if(p){p.src=v?(v.startsWith('http')?v:'../'+v.replace(/^\/+/,'')):'';p.hidden=!v;}}catch{}}
function show(){loadAdminLogo();loadNotifications().catch(()=>{});startNotificationPolling();$('#loginView').classList.add('hide');$('#app').classList.remove('hide');$('#who').textContent=(profile.full_name||'Staff')+' · '+profile.role;$('#rolePill').textContent=profile.role;applyRoleNavigation();route(location.hash.slice(1)||'dashboard')}
function applyRoleNavigation(){const r=String(profile?.role||'').toLowerCase();const map={dashboard:true,bookings:['owner','general_manager','reception_manager'].includes(r),restaurant:['owner','general_manager','reception_manager','chef','barista'].includes(r),inventory:['owner','general_manager','chef','barista','grounds_cleaning'].includes(r),menu:['owner','general_manager','chef','barista'].includes(r),services:['owner','general_manager','reception_manager','head_swimming_coach','swimming_coach'].includes(r),content:['owner','general_manager','website_manager'].includes(r),reviews:['owner','general_manager','reception_manager','website_manager'].includes(r),social:['owner','general_manager','website_manager'].includes(r),staff:['owner'].includes(r),reports:['owner','general_manager','reception_manager'].includes(r),settings:['owner'].includes(r)};$$('[data-tab]').forEach(a=>{const k=a.dataset.tab;a.style.display=map[k]===true||map[k]?.includes(r)?'block':'none'});if(map.staff!==true)$('#staffHelp').textContent='Staff accounts are managed by the owner.'}
let notificationInitialized=false;let notificationIds=new Set();let notificationPoll=null;function showAdminToast(title,message){let t=document.getElementById('adminToast');if(!t){t=document.createElement('div');t.id='adminToast';t.style.cssText='position:fixed;right:18px;bottom:18px;z-index:200;background:#1b4332;color:#fff;padding:14px 16px;border-radius:12px;box-shadow:0 8px 30px #0003;max-width:360px';document.body.appendChild(t)}t.innerHTML='<strong>'+esc(title)+'</strong><div style="margin-top:4px">'+esc(message||'')+'</div>';setTimeout(()=>t.remove(),7000);}function notificationTarget(n){const t=String(n.reference_type||'').toLowerCase();if(t==='booking'||t==='bookings')return 'bookings';if(t==='order'||t==='orders')return 'restaurant';if(t==='review'||t==='reviews')return 'reviews';return 'dashboard'}
async function openNotification(n){const target=notificationTarget(n);if(n.id)await api('/rest/v1/notifications?id=eq.'+encodeURIComponent(n.id),{method:'PATCH',body:JSON.stringify({is_read:true})}).catch(()=>{});if(n.reference_id&&target==='bookings'){history.replaceState(null,'','#bookings');route('bookings');setTimeout(()=>{const row=document.querySelector('[data-b="'+CSS.escape(n.reference_id)+'"]');if(row){row.scrollIntoView({behavior:'smooth',block:'center'});row.closest('tr')?.classList.add('highlight')}} ,100);return}history.replaceState(null,'','#'+target);route(target)}
async function loadNotifications(){if(!session?.user?.id)return;const rows=await api('/rest/v1/notifications?select=*&recipient_user_id=eq.'+session.user.id+'&order=created_at.desc&limit=30');if(notificationInitialized){rows.filter(x=>!notificationIds.has(x.id)).reverse().forEach(x=>showAdminToast(x.title,x.message));}notificationIds=new Set(rows.map(x=>x.id));notificationInitialized=true;bindNotificationClicks();const unread=rows.filter(x=>!x.is_read).length;$('#notificationCount').textContent=String(unread);$('#notificationList').innerHTML=rows.length?rows.map(x=>'<div class="cardx notification-item" data-notification="'+esc(x.id)+'" style="margin-bottom:8px;cursor:pointer;opacity:'+(x.is_read?'0.7':'1')+'"><strong>'+esc(x.title)+'</strong><div>'+esc(x.message||'')+'</div><small class="muted">'+esc(new Date(x.created_at).toLocaleString())+'</small></div>').join(''):'<div class="state">No notifications.</div>';}
function toggleNotifications(){const p=$('#notificationPanel');p.style.display=p.style.display==='none'?'block':'none';if(p.style.display==='block')loadNotifications().catch(msg)}
function startNotificationPolling(){if(notificationPoll)clearInterval(notificationPoll);notificationPoll=setInterval(()=>loadNotifications().catch(()=>{}),15000);}
function bindNotificationClicks(){$('.notification-item').forEach(el=>el.onclick=async()=>{try{const rows=await api('/rest/v1/notifications?id=eq.'+encodeURIComponent(el.dataset.notification));if(rows?.[0])await openNotification(rows[0]);}catch(e){msg(e)}})}
async function markNotificationsRead(){await api('/rest/v1/notifications?recipient_user_id=eq.'+session.user.id+'&is_read=eq.false',{method:'PATCH',body:JSON.stringify({is_read:true})});loadNotifications()}
function route(x){tab=x||'dashboard';$$('[data-tab]').forEach(a=>a.classList.toggle('active',a.dataset.tab===tab));$$('.tab').forEach(s=>s.classList.toggle('active',s.id===tab));const f={dashboard:loadDashboard,bookings:loadBookings,restaurant:loadOrders,inventory:loadInventory,menu:loadMenu,services:loadServices,content:loadContent,reviews:loadReviews,social:loadSocial,staff:loadStaff,reports:loadReport,settings:loadSettings};(f[tab]||loadDashboard)().catch(msg)}
async function loadDashboard(){const d=today();const [b,o,i]=await Promise.all([api('/rest/v1/bookings?select=id,status&booking_date=eq.'+d),api('/rest/v1/orders?select=id,status&status=not.eq.completed&status=not.eq.cancelled'),api('/rest/v1/inventory_items?select=id,reorder_level')]);const sm=await api('/rest/v1/stock_movements?select=item_id,quantity,movement_type');const stock={};sm.forEach(x=>stock[x.item_id]=(stock[x.item_id]||0)+(String(x.movement_type).toLowerCase()==='out'?-1:1)*Number(x.quantity||0));$('#mBookings').textContent=b.length;$('#mPending').textContent=b.filter(x=>x.status==='pending').length;$('#mOrders').textContent=o.length;$('#mLow').textContent=i.filter(x=>(stock[x.id]||0)<=Number(x.reorder_level||0)).length;$('#todayOps').textContent='Live data connected.'}
function today(){return new Date().toISOString().slice(0,10)}
async function cancelBooking(id){modal('Cancel booking','<form id="cancelBookingForm" class="form"><p class="muted">Please enter why this booking cannot be accepted.</p><textarea name="reason" rows="4" required maxlength="500" placeholder="Cancellation reason"></textarea><button type="submit" class="btn btn-dark">Cancel booking</button></form>');$('#cancelBookingForm').onsubmit=async e=>{e.preventDefault();const reason=String(new FormData(e.currentTarget).get('reason')||'').trim();if(!reason)return;await api('/rest/v1/bookings?id=eq.'+encodeURIComponent(id),{method:'PATCH',body:JSON.stringify({status:'cancelled',cancellation_reason:reason})});closeModal();await loadBookings()}}
async function loadBookings(){const filter=$('#bookingFilter').value;let q='/rest/v1/bookings?select=*,customers(name,phone)&order=booking_date.desc,start_time.asc';if(filter!=='all')q+='&status=eq.'+filter;const rows=await api(q);$('#bookingTable').innerHTML=rows.length?'<table><tr><th>Date</th><th>Customer</th><th>People</th><th>Total</th><th>Status</th><th></th></tr>'+rows.map(r=>{const active=r.status!=='cancelled'&&r.status!=='completed';const confirmBtn=r.status==='pending'?'<button class="btn" data-b="'+r.id+'" data-s="confirmed">Confirm</button> ':'';const completeBtn=active?'<button class="btn" data-b="'+r.id+'" data-s="completed">Complete</button> ':'';const cancelBtn=active?'<button class="btn" data-cancel-booking="'+r.id+'">Cancel</button>':'';return '<tr><td>'+esc(r.booking_date)+' '+esc(r.start_time||'')+'</td><td>'+esc(r.customers?.name||'')+'<br>'+esc(r.customers?.phone||'')+'</td><td>'+r.people+'</td><td>UGX '+money(r.total)+'</td><td>'+esc(r.status)+'</td><td class="actions">'+confirmBtn+completeBtn+cancelBtn+'</td></tr>'}).join('')+'</table>':'<div class="state">No bookings.</div>';$('[data-b]').forEach(x=>x.onclick=async()=>{try{await api('/rest/v1/bookings?id=eq.'+encodeURIComponent(x.dataset.b),{method:'PATCH',body:JSON.stringify({status:x.dataset.s})});await loadBookings()}catch(e){msg(e)}});$('[data-cancel-booking]').forEach(x=>x.onclick=()=>cancelBooking(x.dataset.cancelBooking));loadBuffets()}
async function loadBuffets(){const [b,items]=await Promise.all([api('/rest/v1/booking_bundles?select=*&order=sort_order.asc'),api('/rest/v1/booking_bundle_items?select=*&order=sort_order.asc')]);$('#buffetTable').innerHTML='<table><tr><th>Name</th><th>Price/person</th><th>Contents</th><th>Active</th><th></th></tr>'+b.map(x=>'<tr><td>'+esc(x.name)+'</td><td>UGX '+money(x.price_per_person)+'</td><td>'+items.filter(i=>i.bundle_id===x.id&&i.active).map(i=>esc(i.name)+(i.description?' — '+esc(i.description):'')).join('<br>')+'</td><td>'+x.active+'</td><td><button class="btn" data-buffet="'+x.id+'">Edit</button></td></tr>').join('')+'</table>';$$('[data-buffet]').forEach(x=>x.onclick=()=>editBuffet(x.dataset.buffet))}
async function editBuffet(id){const rows=await api('/rest/v1/booking_bundles?id=eq.'+id);const b=rows[0];const items=await api('/rest/v1/booking_bundle_items?bundle_id=eq.'+id+'&order=sort_order.asc');modal('Edit buffet','<form id="bf" class="form"><input name="name" value="'+esc(b.name)+'" placeholder="Name" required><input name="price" type="number" value="'+b.price_per_person+'" placeholder="Price per person"><textarea name="description" placeholder="Description">'+esc(b.description||'')+'</textarea><label>Active <input name="active" type="checkbox" '+(b.active?'checked':'')+'></label><textarea name="contents" placeholder="One included item per line">'+items.map(i=>i.name+(i.description?' | '+i.description:'')).join('\n')+'</textarea><button class="btn btn-dark">Save</button></form>');$('#bf').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);await api('/rest/v1/booking_bundles?id=eq.'+id,{method:'PATCH',body:JSON.stringify({name:f.get('name'),price_per_person:Number(f.get('price')||0),price_on_request:Number(f.get('price')||0)<=0,description:f.get('description'),active:f.get('active')==='on'})});await api('/rest/v1/booking_bundle_items?bundle_id=eq.'+id,{method:'DELETE'});for(const [n,line] of String(f.get('contents')||'').split('\n').map(x=>x.trim()).filter(Boolean).entries()){const [name,...d]=line.split('|');await api('/rest/v1/booking_bundle_items',{method:'POST',body:JSON.stringify({bundle_id:id,name:name.trim(),description:d.join('|').trim()||null,sort_order:n,active:true})})}closeModal();loadBuffets()}}
async function addBuffet(){modal('Add buffet','<form id="bf" class="form"><input name="name" placeholder="Buffet name" required><input name="price" type="number" value="0" placeholder="Price per person"><textarea name="description" placeholder="Description"></textarea><input name="sort" type="number" value="0" placeholder="Sort order"><textarea name="contents" placeholder="One included item per line"></textarea><label>Active <input name="active" type="checkbox" checked></label><button class="btn btn-dark">Save</button></form>');$('#bf').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),r=await api('/rest/v1/booking_bundles',{method:'POST',body:JSON.stringify({name:f.get('name'),price_per_person:Number(f.get('price')||0),price_on_request:Number(f.get('price')||0)<=0,description:f.get('description')||null,sort_order:Number(f.get('sort')||0),active:f.get('active')==='on'})}),id=r?.[0]?.id;if(id)for(const [n,line] of String(f.get('contents')||'').split('\n').map(x=>x.trim()).filter(Boolean).entries()){const [name,...d]=line.split('|');await api('/rest/v1/booking_bundle_items',{method:'POST',body:JSON.stringify({bundle_id:id,name:name.trim(),description:d.join('|').trim()||null,sort_order:n,active:true})})}closeModal();loadBuffets()}}
async function loadOrders(){const filter=$('#orderStatusFilter').value;let q='/rest/v1/orders?select=*&order=created_at.desc';if(filter!=='all')q+='&status=eq.'+filter;const rows=await api(q);$('#ordersTable').innerHTML='<table><tr><th>Order</th><th>Status</th><th>Payment</th><th>Total</th><th></th></tr>'+rows.map(r=>{const confirmBtn=(r.status==='pending'||r.status==='open')?'<button class="btn" data-confirm="'+r.id+'">Confirm</button> ':'';return '<tr><td>#'+esc(r.id.slice(0,8))+'<br>'+esc(r.source)+'</td><td>'+esc(r.status)+'</td><td>'+esc(r.payment_status)+'</td><td>UGX '+money(r.total)+'</td><td class="actions">'+confirmBtn+'<button class="btn" data-paid="'+r.id+'">Mark paid</button> <button class="btn" data-done="'+r.id+'">Complete</button> <button class="btn" data-cancel="'+r.id+'">Cancel</button> <button class="btn" data-items="'+r.id+'">Items</button></td></tr>'}).join('')+'</table>';$$('[data-confirm]').forEach(x=>x.onclick=()=>setOrder(x.dataset.confirm,'confirmed',null));$$('[data-paid]').forEach(x=>x.onclick=()=>setOrder(x.dataset.paid,null,'paid'));$$('[data-done]').forEach(x=>x.onclick=()=>setOrder(x.dataset.done,'completed',null));$$('[data-cancel]').forEach(x=>x.onclick=()=>{if(confirm('Cancel this order?'))setOrder(x.dataset.cancel,'cancelled',null)});$$('[data-items]').forEach(x=>x.onclick=()=>loadOrderItems(x.dataset.items))}
async function setOrder(id,status,payment){const body={p_order_id:id,p_status:status,p_payment_status:payment};await api('/rest/v1/rpc/admin_set_order_status',{method:'POST',body:JSON.stringify(body)});loadOrders()}
async function loadOrderItems(id){const r=await api('/rest/v1/order_items?select=id,qty,unit_price,item_name_snapshot,notes&order_id=eq.'+id);$('#orderItemsTable').innerHTML='<table><tr><th>Item</th><th>Qty</th><th>Price</th><th>Notes</th></tr>'+r.map(x=>'<tr><td>'+esc(x.item_name_snapshot||'')+'</td><td>'+x.qty+'</td><td>UGX '+money(x.unit_price)+'</td><td>'+esc(x.notes||'')+'</td></tr>').join('')+'</table>'}
async function loadInventory(){const [rows,sm]=await Promise.all([api('/rest/v1/inventory_items?select=*&order=name.asc'),api('/rest/v1/stock_movements?select=item_id,quantity,movement_type')]);const stock={};sm.forEach(x=>stock[x.item_id]=(stock[x.item_id]||0)+(String(x.movement_type).toLowerCase()==='out'?-1:1)*Number(x.quantity||0));$('#inventoryTable').innerHTML='<table><tr><th>Name</th><th>Category</th><th>Unit</th><th>Stock</th><th>Reorder</th><th></th></tr>'+rows.map(x=>'<tr><td>'+esc(x.name)+'</td><td>'+esc(x.category||'')+'</td><td>'+esc(x.unit)+'</td><td>'+(stock[x.id]||0)+'</td><td>'+x.reorder_level+'</td><td><button class="btn" data-inv="'+x.id+'">Edit</button></td></tr>').join('')+'</table>';const recipes=await api('/rest/v1/menu_recipes?select=id,menu_item_id,inventory_item_id,quantity,menu_items(name),inventory_items(name,unit)&order=created_at.asc');$('#recipeTable').innerHTML='<div class="toolbar"><button class="btn" id="newRecipe">Add ingredient mapping</button></div>'+(recipes.length?'<table><tr><th>Menu item</th><th>Ingredient</th><th>Quantity</th><th></th></tr>'+recipes.map(r=>'<tr><td>'+esc(r.menu_items?.name||r.menu_item_id)+'</td><td>'+esc(r.inventory_items?.name||r.inventory_item_id)+' ('+esc(r.inventory_items?.unit||'')+')</td><td>'+esc(r.quantity)+'</td><td><button class="btn" data-recipe-edit="'+r.id+'">Edit</button> <button class="btn" data-recipe-delete="'+r.id+'">Delete</button></td></tr>').join('')+'</table>':'<div class="state">No recipe mappings yet.</div>');$('#newRecipe').onclick=manageRecipe;$$('[data-recipe-edit]').forEach(x=>x.onclick=()=>editRecipe(x.dataset.recipeEdit));$$('[data-recipe-delete]').forEach(x=>x.onclick=async()=>{if(confirm('Delete this recipe mapping?')){await api('/rest/v1/menu_recipes?id=eq.'+x.dataset.recipeDelete,{method:'DELETE'});loadInventory()}});$$('[data-inv]').forEach(x=>x.onclick=()=>editInventory(x.dataset.inv));await Promise.all([loadDailyStock(),loadPurchases(),loadStockMovements()])}
async function loadDailyStock(){const d=$('#stockRunDate').value||today();$('#stockRunDate').value=d;const [items,movs,counts,before]=await Promise.all([api('/rest/v1/inventory_items?select=id,name,unit&active=eq.true&order=name.asc'),api('/rest/v1/stock_movements?select=item_id,quantity,movement_type,reason,created_at&created_at=gte.'+d+'T00:00:00&created_at=lte.'+d+'T23:59:59'),api('/rest/v1/inventory_daily_counts?select=inventory_item_id,physical_quantity&count_date=eq.'+d),api('/rest/v1/stock_movements?select=item_id,quantity,movement_type&created_at=lt.'+d+'T00:00:00')]);const opening={};before.forEach(x=>opening[x.item_id]=(opening[x.item_id]||0)+(String(x.movement_type).toLowerCase()==='out'?-1:1)*Number(x.quantity||0));const day={};movs.forEach(x=>{const z=day[x.item_id]||{added:0,pos:0,waste:0,owner:0,other:0};const q=Number(x.quantity||0),r=String(x.reason||'').toLowerCase();if(String(x.movement_type).toLowerCase()!=='out')z.added+=q;else if(r.startsWith('order '))z.pos+=q;else if(r==='waste')z.waste+=q;else if(r==='owner taken home')z.owner+=q;else z.other+=q;day[x.item_id]=z});const counted=Object.fromEntries(counts.map(x=>[x.inventory_item_id,Number(x.physical_quantity)]));$('#dailyStockTable').innerHTML='<table><tr><th>Item</th><th>Opening</th><th>Added</th><th>POS Used</th><th>Waste</th><th>Owner Home</th><th>Other</th><th>Expected</th><th>Physical</th><th>Variance</th></tr>'+items.map(x=>{const z=day[x.id]||{added:0,pos:0,waste:0,owner:0,other:0},op=Number(opening[x.id]||0),expected=op+z.added-z.pos-z.waste-z.owner-z.other,p=counted[x.id];return '<tr><td>'+esc(x.name)+'<br><small>'+esc(x.unit)+'</small></td><td>'+op+'</td><td>'+z.added+'</td><td>'+z.pos+'</td><td>'+z.waste+'</td><td>'+z.owner+'</td><td>'+z.other+'</td><td>'+expected+'</td><td>'+(p==null?'—':p)+'</td><td>'+(p==null?'—':p-expected)+'</td></tr>'}).join('')+'</table>'}
async function loadPurchases(){const orders=await api('/rest/v1/purchase_orders?select=*&order=created_at.desc');let items=[];if(orders.length)items=await api('/rest/v1/purchase_order_items?select=*,inventory_items(name,unit)&purchase_order_id=in.('+orders.map(x=>x.id).join(',')+')');$('#purchaseOrdersTable').innerHTML=orders.length?'<table><tr><th>Supplier</th><th>Reference</th><th>Status</th><th>Total</th><th></th></tr>'+orders.map(o=>'<tr><td>'+esc(o.supplier||'')+'</td><td>'+esc(o.reference||'')+'</td><td>'+esc(o.status)+'</td><td>UGX '+money(o.total)+'</td><td>'+(o.status!=='received'&&o.status!=='cancelled'?'<button class="btn" data-receive-po="'+o.id+'">Receive</button> ':'')+'<button class="btn" data-edit-po="'+o.id+'">Edit</button></td></tr>').join('')+'</table>':'<div class="state">No purchase orders yet.</div>';$$('[data-receive-po]').forEach(x=>x.onclick=()=>receivePurchase(x.dataset.receivePo));$$('[data-edit-po]').forEach(x=>x.onclick=()=>editPurchase(x.dataset.editPo))}
async function editPurchase(id=null){const inv=await api('/rest/v1/inventory_items?select=id,name,unit&active=eq.true&order=name.asc');let po=null,items=[];if(id){po=(await api('/rest/v1/purchase_orders?id=eq.'+id))[0];items=await api('/rest/v1/purchase_order_items?select=*&purchase_order_id=eq.'+id)}const line=(i={})=>'<div class="purchase-line" style="display:grid;grid-template-columns:2fr 1fr 1fr;gap:8px;margin:6px 0"><select name="item">'+inv.map(x=>'<option value="'+x.id+'" '+(x.id===i.inventory_item_id?'selected':'')+'>'+esc(x.name)+' ('+esc(x.unit)+')</option>').join('')+'</select><input name="qty" type="number" step="0.001" min="0.001" value="'+(i.ordered_quantity||'')+'" placeholder="Qty"><input name="cost" type="number" step="0.01" min="0" value="'+(i.unit_cost||'')+'" placeholder="Unit cost"></div>';modal(id?'Edit purchase order':'New purchase order','<form id="po" class="form"><input name="supplier" value="'+esc(po?.supplier||'')+'" placeholder="Supplier"><input name="reference" value="'+esc(po?.reference||'')+'" placeholder="Supplier invoice / reference"><textarea name="notes" placeholder="Notes">'+esc(po?.notes||'')+'</textarea><div id="poLines">'+(items.length?items.map(line).join(''):line())+'</div><button type="button" class="btn" id="addPOLine">Add item</button> <button class="btn btn-dark">Save purchase order</button></form>');$('#addPOLine').onclick=()=>$('#poLines').insertAdjacentHTML('beforeend',line());$('#po').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),rows=[...e.currentTarget.querySelectorAll('.purchase-line')].map(r=>({inventory_item_id:r.querySelector('[name=item]').value,ordered_quantity:Number(r.querySelector('[name=qty]').value||0),unit_cost:Number(r.querySelector('[name=cost]').value||0)})).filter(x=>x.ordered_quantity>0);if(!rows.length)return alert('Add at least one item.');let oid=id;if(!oid){const r=await api('/rest/v1/purchase_orders',{method:'POST',body:JSON.stringify({supplier:f.get('supplier')||null,reference:f.get('reference')||null,notes:f.get('notes')||null,status:'ordered',ordered_at:new Date().toISOString(),created_by:session.user.id,total:rows.reduce((a,x)=>a+x.ordered_quantity*x.unit_cost,0)})});oid=r[0].id}else{await api('/rest/v1/purchase_orders?id=eq.'+id,{method:'PATCH',body:JSON.stringify({supplier:f.get('supplier')||null,reference:f.get('reference')||null,notes:f.get('notes')||null,total:rows.reduce((a,x)=>a+x.ordered_quantity*x.unit_cost,0)})});await api('/rest/v1/purchase_order_items?purchase_order_id=eq.'+id,{method:'DELETE'})}for(const x of rows)await api('/rest/v1/purchase_order_items',{method:'POST',body:JSON.stringify({...x,purchase_order_id:oid})});closeModal();loadPurchases()}}
async function receivePurchase(id){const items=await api('/rest/v1/purchase_order_items?select=*,inventory_items(name,unit)&purchase_order_id=eq.'+id);modal('Receive purchase','<form id="receive" class="form">'+items.map(i=>'<label>'+esc(i.inventory_items?.name||'')+' ('+esc(i.inventory_items?.unit||'')+')<input name="'+i.id+'" type="number" step="0.001" min="0" max="'+i.ordered_quantity+'" value="'+Math.max(0,Number(i.ordered_quantity)-Number(i.received_quantity||0))+'"></label>').join('')+'<button class="btn btn-dark">Receive stock</button></form>');$('#receive').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);for(const i of items){const q=Number(f.get(i.id)||0);if(q>0){await api('/rest/v1/stock_movements',{method:'POST',body:JSON.stringify({item_id:i.inventory_item_id,quantity:q,movement_type:'in',reason:'Purchase '+id,staff_id:session.user.id})});await api('/rest/v1/purchase_order_items?id=eq.'+i.id,{method:'PATCH',body:JSON.stringify({received_quantity:Number(i.received_quantity||0)+q})})}}const fresh=await api('/rest/v1/purchase_order_items?select=ordered_quantity,received_quantity&purchase_order_id=eq.'+id);const done=fresh.every(x=>Number(x.received_quantity)>=Number(x.ordered_quantity)),some=fresh.some(x=>Number(x.received_quantity)>0);await api('/rest/v1/purchase_orders?id=eq.'+id,{method:'PATCH',body:JSON.stringify({status:done?'received':(some?'partially_received':'ordered'),received_at:done?new Date().toISOString():null})});closeModal();loadPurchases();loadDailyStock();loadInventory()}}
async function setOpeningStock(){const inv=await api('/rest/v1/inventory_items?select=id,name,unit&active=eq.true&order=name.asc');modal('Set opening stock','<form id="openingStockForm" class="form"><p class="muted">Enter the stock physically available when Kiteezi starts its inventory records. This creates auditable opening-balance movements.</p>'+inv.map(x=>'<label>'+esc(x.name)+' ('+esc(x.unit)+')<input name="'+x.id+'" type="number" step="0.001" min="0" placeholder="Opening quantity"></label>').join('')+'<button class="btn btn-dark">Save opening stock</button></form>');$('#openingStockForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const rows=inv.map(x=>({item_id:x.id,quantity:Number(f.get(x.id)||0)})).filter(x=>x.quantity>0);if(!rows.length)return alert('Enter at least one opening quantity.');for(const x of rows){await api('/rest/v1/stock_movements',{method:'POST',body:JSON.stringify({item_id:x.item_id,quantity:x.quantity,movement_type:'in',reason:'Opening Balance',staff_id:session.user.id})})}closeModal();loadInventory();loadDailyStock()}}
async function addStockAdjustment(){const inv=await api('/rest/v1/inventory_items?select=id,name,unit&active=eq.true&order=name.asc');modal('Add stock movement','<form id="adj" class="form"><select name="item">'+inv.map(x=>'<option value="'+x.id+'">'+esc(x.name)+' ('+esc(x.unit)+')</option>').join('')+'</select><select name="type"><option value="out">Stock out</option><option value="in">Stock in</option></select><select name="reason"><option>Waste</option><option>Owner Taken Home</option><option>Other Adjustment</option></select><input name="qty" type="number" step="0.001" min="0.001" placeholder="Quantity" required><textarea name="notes" placeholder="Notes"></textarea><button class="btn btn-dark">Save movement</button></form>');$('#adj').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);await api('/rest/v1/stock_movements',{method:'POST',body:JSON.stringify({item_id:f.get('item'),quantity:Number(f.get('qty')),movement_type:f.get('type'),reason:f.get('reason')+(f.get('notes')?' — '+f.get('notes'):''),staff_id:session.user.id})});closeModal();loadInventory()}}
async function loadStockMovements(){const r=await api('/rest/v1/stock_movements?select=*,inventory_items(name,unit)&order=created_at.desc&limit=100');$('#stockMovementTable').innerHTML=r.length?'<table><tr><th>Date</th><th>Item</th><th>Movement</th><th>Qty</th><th>Reason</th></tr>'+r.map(x=>'<tr><td>'+esc(x.created_at?.slice(0,16)||'')+'</td><td>'+esc(x.inventory_items?.name||x.item_id)+'</td><td>'+esc(x.movement_type)+'</td><td>'+x.quantity+'</td><td>'+esc(x.reason||'')+'</td></tr>').join('')+'</table>':'<div class="state">No stock movements yet.</div>'}
async function editInventory(id=null){const x=id?(await api('/rest/v1/inventory_items?id=eq.'+id))[0]:{name:'',unit:'',category:'',reorder_level:0,active:true};modal(id?'Inventory item':'Add inventory item','<form id="inv" class="form"><input name="name" value="'+esc(x.name)+'" placeholder="Ingredient name" required><input name="unit" value="'+esc(x.unit)+'" placeholder="kg, litre, piece…" required><input name="category" value="'+esc(x.category||'')+'" placeholder="Category"><input name="reorder" type="number" step="0.001" value="'+(x.reorder_level||0)+'" placeholder="Reorder level"><label>Active <input name="active" type="checkbox" '+(x.active?'checked':'')+'></label><button class="btn btn-dark">Save</button></form>');$('#inv').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),body={name:f.get('name'),unit:f.get('unit'),category:f.get('category')||null,reorder_level:Number(f.get('reorder')||0),active:f.get('active')==='on'};await api(id?'/rest/v1/inventory_items?id=eq.'+id:'/rest/v1/inventory_items',{method:id?'PATCH':'POST',body:JSON.stringify(body)});closeModal();loadInventory()}}
async function manageRecipe(existingId=null){const [m,i]=await Promise.all([api('/rest/v1/menu_items?select=id,name&order=name.asc'),api('/rest/v1/inventory_items?select=id,name,unit&active=eq.true&order=name.asc')]);let existing=null;if(existingId)existing=(await api('/rest/v1/menu_recipes?id=eq.'+existingId))[0];modal(existing?'Edit recipe mapping':'Add recipe mapping','<form id="recipe" class="form"><select name="menu">'+m.map(x=>'<option value="'+x.id+'" '+(existing?.menu_item_id===x.id?'selected':'')+'>'+esc(x.name)+'</option>').join('')+'</select><select name="inv">'+i.map(x=>'<option value="'+x.id+'" '+(existing?.inventory_item_id===x.id?'selected':'')+'>'+esc(x.name)+' ('+esc(x.unit)+')</option>').join('')+'</select><input name="qty" type="number" step="0.001" min="0.001" value="'+(existing?.quantity||'')+'" placeholder="Quantity used" required><button class="btn btn-dark">Save</button></form>');$('#recipe').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),body={menu_item_id:f.get('menu'),inventory_item_id:f.get('inv'),quantity:Number(f.get('qty'))};await api(existingId?'/rest/v1/menu_recipes?id=eq.'+existingId:'/rest/v1/menu_recipes',{method:existingId?'PATCH':'POST',body:JSON.stringify(body)});closeModal();loadInventory()}}
async function editRecipe(id){return manageRecipe(id)}
async function loadMenu(){const r=await api('/rest/v1/menu_items?select=*,menu_categories(name)&order=name.asc');$('#menuTable').innerHTML='<table><tr><th>Name</th><th>Category</th><th>Price</th><th>Stock</th><th></th></tr>'+r.map(x=>'<tr><td>'+esc(x.name)+'</td><td>'+esc(x.menu_categories?.name||'')+'</td><td>'+((x.price_on_request)?'Ask':'UGX '+money(x.price))+'</td><td>'+x.in_stock+'</td><td><button class="btn" data-menu="'+x.id+'">Edit</button></td></tr>').join('')+'</table>';$$('[data-menu]').forEach(x=>x.onclick=()=>editMenu(x.dataset.menu))}
async function editMenu(id=null){const cats=await api('/rest/v1/menu_categories?select=id,name&active=eq.true&order=sort_order.asc,name.asc');const x=id?(await api('/rest/v1/menu_items?id=eq.'+id))[0]:{name:'',description:'',price:0,img_url:'',price_on_request:false,in_stock:true,category_id:null};modal(id?'Menu item':'Add menu item','<form id="mi" class="form"><input name="name" value="'+esc(x.name)+'" placeholder="Name" required><select name="category"><option value="">No category</option>'+cats.map(q=>'<option value="'+q.id+'" '+(x.category_id===q.id?'selected':'')+'>'+esc(q.name)+'</option>').join('')+'</select><textarea name="description" placeholder="Description">'+esc(x.description||'')+'</textarea><input name="price" type="number" step="0.01" value="'+(x.price||0)+'" placeholder="Price"><input name="img" value="'+esc(x.img_url||'')+'" placeholder="Image URL"><label>Price on request <input name="por" type="checkbox" '+(x.price_on_request?'checked':'')+'></label><label>In stock <input name="stock" type="checkbox" '+(x.in_stock?'checked':'')+'></label><button class="btn btn-dark">Save</button></form>');$('#mi').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),body={name:f.get('name'),category_id:f.get('category')||null,description:f.get('description')||null,price:Number(f.get('price')||0),img_url:f.get('img')||null,price_on_request:f.get('por')==='on',in_stock:f.get('stock')==='on'};await api(id?'/rest/v1/menu_items?id=eq.'+id:'/rest/v1/menu_items',{method:id?'PATCH':'POST',body:JSON.stringify(body)});closeModal();loadMenu()}}
async function loadServices(){const [s,sp]=await Promise.all([api('/rest/v1/services?select=*&order=name.asc'),api('/rest/v1/sports?select=*&order=name.asc')]);$('#servicesTable').innerHTML='<table><tr><th>Name</th><th>Price</th><th>Pricing</th><th>Active</th><th></th></tr>'+s.map(x=>'<tr><td>'+esc(x.name)+'</td><td>UGX '+money(x.price)+'</td><td>'+esc(x.pricing_mode||'fixed')+'</td><td>'+x.active+'</td><td><button class="btn" data-svc="'+x.id+'">Edit</button></td></tr>').join('')+'</table>';$('#sportsTable').innerHTML='<table><tr><th>Sport</th><th>Description</th><th>Active</th><th></th></tr>'+sp.map(x=>'<tr><td>'+esc(x.name)+'</td><td>'+esc(x.description||'')+'</td><td>'+x.active+'</td><td><button class="btn" data-sport="'+x.id+'">Edit</button></td></tr>').join('')+'</table>';$$('[data-svc]').forEach(x=>x.onclick=()=>editService(x.dataset.svc));$$('[data-sport]').forEach(x=>x.onclick=()=>editSport(x.dataset.sport))}
async function editService(id=null){const x=id?(await api('/rest/v1/services?id=eq.'+id))[0]:{name:'',description:'',price:0,team_threshold:null,small_group_price:null,full_team_price:null,active:true,pricing_mode:'fixed'};modal(id?'Service':'Add service','<form id="svc" class="form"><input name="name" value="'+esc(x.name)+'" placeholder="Service name" required><textarea name="description" placeholder="Description">'+esc(x.description||'')+'</textarea><input name="price" type="number" value="'+(x.price||0)+'" placeholder="Base price"><input name="duration" type="number" value="'+(x.duration_minutes||'')+'" placeholder="Duration minutes"><select name="pricing"><option value="fixed" '+(x.pricing_mode==='fixed'?'selected':'')+'>Fixed</option><option value="per_person" '+(x.pricing_mode==='per_person'?'selected':'')+'>Per person</option><option value="team" '+(x.pricing_mode==='team'?'selected':'')+'>Team</option></select><input name="threshold" type="number" value="'+(x.team_threshold||'')+'" placeholder="Team threshold"><input name="small" type="number" value="'+(x.small_group_price||'')+'" placeholder="Small group price"><input name="full" type="number" value="'+(x.full_team_price||'')+'" placeholder="Full team price"><label>Active <input name="active" type="checkbox" '+(x.active?'checked':'')+'></label><button class="btn btn-dark">Save</button></form>');$('#svc').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),body={name:f.get('name'),description:f.get('description')||null,price:Number(f.get('price')||0),duration_minutes:Number(f.get('duration')||0)||null,pricing_mode:f.get('pricing'),team_threshold:Number(f.get('threshold')||0)||null,small_group_price:Number(f.get('small')||0)||null,full_team_price:Number(f.get('full')||0)||null,active:f.get('active')==='on'};await api(id?'/rest/v1/services?id=eq.'+id:'/rest/v1/services',{method:id?'PATCH':'POST',body:JSON.stringify(body)});closeModal();loadServices()}}
async function editSport(id=null){const x=id?(await api('/rest/v1/sports?id=eq.'+id))[0]:{name:'',description:'',active:true};modal(id?'Sport':'Add sport','<form id="sport" class="form"><input name="name" value="'+esc(x.name)+'" placeholder="Sport name" required><textarea name="description" placeholder="Description">'+esc(x.description||'')+'</textarea><label>Active <input name="active" type="checkbox" '+(x.active?'checked':'')+'></label><button class="btn btn-dark">Save</button></form>');$('#sport').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),body={name:f.get('name'),description:f.get('description')||null,active:f.get('active')==='on'};await api(id?'/rest/v1/sports?id=eq.'+id:'/rest/v1/sports',{method:id?'PATCH':'POST',body:JSON.stringify(body)});closeModal();loadServices()}}
async function loadContent(){const [p,m,a]=await Promise.all([api('/rest/v1/cms_pages?select=*&order=slug.asc'),api('/rest/v1/media?select=*&order=page_slug.asc,sort_order.asc'),api('/rest/v1/announcements?select=*&order=starts_at.desc')]);$('#pagesTable').innerHTML='<table><tr><th>Slug</th><th>Title</th><th>Published</th><th></th></tr>'+p.map(x=>'<tr><td>'+esc(x.slug)+'</td><td>'+esc(x.title||'')+'</td><td>'+x.published+'</td><td><button class="btn" data-page="'+x.id+'">Edit</button></td></tr>').join('')+'</table>';$('#mediaTable').innerHTML='<table><tr><th>Page</th><th>Title</th><th>URL</th><th>Active</th><th></th></tr>'+m.map(x=>'<tr><td>'+esc(x.page_slug||'')+'</td><td>'+esc(x.title||'')+'</td><td>'+esc(x.url)+'</td><td>'+x.active+'</td><td><button class="btn" data-media="'+x.id+'">Edit</button></td></tr>').join('')+'</table>';$('#announcementsTable').innerHTML='<table><tr><th>Title</th><th>Published</th><th>Body</th><th></th></tr>'+a.map(x=>'<tr><td>'+esc(x.title)+'</td><td>'+x.published+'</td><td>'+esc(x.body||'')+'</td><td><button class="btn" data-ann="'+x.id+'">Edit</button></td></tr>').join('')+'</table>';$$('[data-page]').forEach(x=>x.onclick=()=>editPage(x.dataset.page));$$('[data-media]').forEach(x=>x.onclick=()=>editMedia(x.dataset.media));$$('[data-ann]').forEach(x=>x.onclick=()=>editAnnouncement(x.dataset.ann))}
function table(h,rows,fn){return '<table><tr>'+h.map(x=>'<th>'+x+'</th>').join('')+'</tr>'+rows.map(x=>'<tr>'+fn(x).map(v=>'<td>'+((typeof v==='string'&&v.trim().startsWith('<button'))?v:esc(v))+'</td>').join('')+'</tr>').join('')+'</table>'}
async function editPage(id){const x=(await api('/rest/v1/cms_pages?id=eq.'+id))[0];modal('CMS page','<form id="ed" class="form"><input name="title" value="'+esc(x.title||'')+'"><textarea name="content">'+esc(JSON.stringify(x.content||{},null,2))+'</textarea><label>Published <input name="published" type="checkbox" '+(x.published?'checked':'')+'></label><button class="btn btn-dark">Save</button></form>');$('#ed').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);let content={};try{content=JSON.parse(f.get('content')||'{}')}catch{alert('Content must be valid JSON');return}await api('/rest/v1/cms_pages?id=eq.'+id,{method:'PATCH',body:JSON.stringify({title:f.get('title'),content,published:f.get('published')==='on',updated_at:new Date().toISOString()})});closeModal();loadContent()}}
async function editMedia(id){const x=(await api('/rest/v1/media?id=eq.'+id))[0];modal('Media','<form id="ed" class="form"><input name="title" value="'+esc(x.title||'')+'"><input name="url" value="'+esc(x.url)+'" required><input name="alt" value="'+esc(x.alt_text||'')+'"><input name="page" value="'+esc(x.page_slug||'')+'"><input name="sort" type="number" value="'+x.sort_order+'"><label>Active <input name="active" type="checkbox" '+(x.active?'checked':'')+'></label><button class="btn btn-dark">Save</button></form>');$('#ed').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);await api('/rest/v1/media?id=eq.'+id,{method:'PATCH',body:JSON.stringify({title:f.get('title'),url:f.get('url'),alt_text:f.get('alt'),page_slug:f.get('page'),sort_order:Number(f.get('sort')||0),active:f.get('active')==='on'})});closeModal();loadContent()}}
async function editAnnouncement(id){const x=(await api('/rest/v1/announcements?id=eq.'+id))[0];modal('Announcement','<form id="ed" class="form"><input name="title" value="'+esc(x.title)+'" required><textarea name="body">'+esc(x.body||'')+'</textarea><label>Published <input name="published" type="checkbox" '+(x.published?'checked':'')+'></label><button class="btn btn-dark">Save</button></form>');$('#ed').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);await api('/rest/v1/announcements?id=eq.'+id,{method:'PATCH',body:JSON.stringify({title:f.get('title'),body:f.get('body'),published:f.get('published')==='on'})});closeModal();loadContent()}}
async function addMedia(){modal('Add media','<form id="mediaForm" class="form"><input name="title" placeholder="Title"><input name="url" placeholder="Image/video URL" required><input name="alt" placeholder="Alt text"><input name="page" placeholder="Page slug"><input name="area" placeholder="Area (e.g. gallery)" value="gallery" required><input name="type" placeholder="Type" value="image"><input name="sort" type="number" value="0"><label>Gallery item <input name="gallery" type="checkbox" checked></label><label>Active <input name="active" type="checkbox" checked></label><button class="btn btn-dark">Save</button></form>');$('#mediaForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);await api('/rest/v1/media',{method:'POST',body:JSON.stringify({title:f.get('title')||null,url:f.get('url'),alt_text:f.get('alt')||null,page_slug:f.get('page')||null,area:f.get('area'),type:f.get('type')||null,sort_order:Number(f.get('sort')||0),is_gallery:f.get('gallery')==='on',active:f.get('active')==='on'})});closeModal();loadContent()}}
async function addAnnouncement(){modal('Add announcement','<form id="annForm" class="form"><input name="title" placeholder="Title" required><textarea name="body" placeholder="Message"></textarea><input name="starts" type="datetime-local"><input name="ends" type="datetime-local"><label>Published <input name="published" type="checkbox"></label><button class="btn btn-dark">Save</button></form>');$('#annForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);await api('/rest/v1/announcements',{method:'POST',body:JSON.stringify({title:f.get('title'),body:f.get('body')||null,starts_at:f.get('starts')?new Date(f.get('starts')).toISOString():null,ends_at:f.get('ends')?new Date(f.get('ends')).toISOString():null,published:f.get('published')==='on'})});closeModal();loadContent()}}
async function loadReviews(){const r=await api('/rest/v1/reviews?select=*&order=created_at.desc');$('#reviewsTable').innerHTML=table(['Name','Rating','Message','Approved',''],r,x=>[x.customer_name,x.rating,x.message,x.approved,'<button class="btn" data-rm="'+x.id+'">Remove</button>']);$$('[data-rm]').forEach(x=>x.onclick=async()=>{if(confirm('Remove this review?')){await api('/rest/v1/reviews?id=eq.'+x.dataset.rm,{method:'DELETE'});loadReviews()}})}
async function loadSocial(){const r=await api('/rest/v1/social_links?select=*&order=sort_order.asc');$('#socialTable').innerHTML=table(['Platform','Label','URL','Active',''],r,x=>[x.platform,x.label,x.url,x.active,'<button class="btn" data-sl="'+x.id+'">Edit</button>']);$$('[data-sl]').forEach(x=>x.onclick=()=>editSocial(x.dataset.sl))}
async function editSocial(id){const x=id?(await api('/rest/v1/social_links?id=eq.'+id))[0]:{platform:'',label:'',url:'',sort_order:0,active:true};modal('Social link','<form id="sl" class="form"><input name="platform" value="'+esc(x.platform)+'" placeholder="Platform"><input name="label" value="'+esc(x.label)+'" placeholder="Label"><input name="url" type="url" value="'+esc(x.url)+'" placeholder="https://..." required><input name="sort" type="number" value="'+x.sort_order+'"><label>Active <input name="active" type="checkbox" '+(x.active?'checked':'')+'></label><button class="btn btn-dark">Save</button></form>');$('#sl').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const body={platform:f.get('platform'),label:f.get('label'),url:f.get('url'),sort_order:Number(f.get('sort')||0),active:f.get('active')==='on'};await api(id?'/rest/v1/social_links?id=eq.'+id:'/rest/v1/social_links',{method:id?'PATCH':'POST',body:JSON.stringify(body)});closeModal();loadSocial()}}
async function loadTeamPositions(){const rows=await api('/rest/v1/team_positions?select=id,department,position,person_name,sort_order,active&order=sort_order.asc');$('#teamPositionsTable').innerHTML='<table><tr><th>Department</th><th>Position</th><th>Person</th><th>Active</th><th></th></tr>'+rows.map(x=>'<tr><td>'+esc(x.department)+'</td><td>'+esc(x.position)+'</td><td>'+esc(x.person_name||'')+'</td><td>'+x.active+'</td><td><button class="btn" data-team-edit="'+x.id+'">Edit</button> <button class="btn" data-team-delete="'+x.id+'">Remove</button></td></tr>').join('')+'</table>';$$('[data-team-edit]').forEach(x=>x.onclick=()=>editTeamPosition(x.dataset.teamEdit));$$('[data-team-delete]').forEach(x=>x.onclick=()=>deleteTeamPosition(x.dataset.teamDelete))}
function editTeamPosition(id){const load=id?api('/rest/v1/team_positions?id=eq.'+id):Promise.resolve([{department:'',position:'',person_name:'',sort_order:100,active:true}]);load.then(rows=>{const x=rows[0];modal(id?'Edit position':'Add position','<form id="teamPositionForm" class="form"><input name="department" required placeholder="Department" value="'+esc(x.department||'')+'"><input name="position" required placeholder="Position" value="'+esc(x.position||'')+'"><input name="person_name" placeholder="Person’s name" value="'+esc(x.person_name||'')+'"><input name="sort_order" type="number" value="'+Number(x.sort_order||100)+'"><label>Active <input name="active" type="checkbox" '+(x.active?'checked':'')+'></label><button class="btn btn-dark" type="submit">Save</button></form>');$('#teamPositionForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const body={department:String(f.get('department')||'').trim(),position:String(f.get('position')||'').trim(),person_name:String(f.get('person_name')||'').trim(),sort_order:Number(f.get('sort_order')||100),active:f.get('active')==='on',updated_at:new Date().toISOString()};await api(id?'/rest/v1/team_positions?id=eq.'+id:'/rest/v1/team_positions',{method:id?'PATCH':'POST',body:JSON.stringify(body)});closeModal();loadTeamPositions()}})}
async function deleteTeamPosition(id){if(!confirm('Remove this public position?'))return;await api('/rest/v1/team_positions?id=eq.'+id,{method:'DELETE'});loadTeamPositions()}
async function addStaff(){const roles=await api('/rest/v1/roles?select=id,name&order=name.asc');const usable=roles.filter(r=>r.name!=='owner');modal('Add staff','<form id="newStaffForm" class="form"><input name="name" placeholder="Full name" required><input name="email" type="email" placeholder="Email address" required><input name="phone" placeholder="Phone"><select name="role" required><option value="">Choose role</option>'+usable.map(r=>'<option value="'+esc(r.name)+'">'+esc(r.name)+'</option>').join('')+'</select><p class="muted">The staff member will receive an invitation and set their own password.</p><button class="btn btn-dark">Send invitation</button></form>');$('#newStaffForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/functions/v1/invite-staff',{method:'POST',body:JSON.stringify({name:String(f.get('name')||'').trim(),email:String(f.get('email')||'').trim(),phone:String(f.get('phone')||'').trim(),role:String(f.get('role')||'').trim()})});alert('Invitation sent.');closeModal();loadStaff()}catch(err){alert(err.message||'Could not send invitation.')}}}
async function loadStaff(){await loadTeamPositions();const [r,roles]=await Promise.all([api('/rest/v1/profiles?select=id,full_name,phone,role,active,created_at&order=full_name.asc'),api('/rest/v1/roles?select=id,name&order=name.asc')]);$('#staffTable').innerHTML='<table><tr><th>Name</th><th>Phone</th><th>Role</th><th>Active</th><th></th></tr>'+r.map(x=>'<tr><td>'+esc(x.full_name)+'</td><td>'+esc(x.phone||'')+'</td><td>'+esc(x.role)+'</td><td>'+x.active+'</td><td><button class="btn" data-staff="'+x.id+'">Edit</button></td></tr>').join('')+'</table>';$$('[data-staff]').forEach(x=>x.onclick=()=>editStaff(x.dataset.staff,roles))}
async function editStaff(id,roles){const x=(await api('/rest/v1/profiles?id=eq.'+id))[0];modal('Staff profile','<form id="staffForm" class="form"><input name="name" value="'+esc(x.full_name||'')+'"><input name="phone" value="'+esc(x.phone||'')+'"><select name="role">'+roles.map(r=>'<option '+(r.name===x.role?'selected':'')+' value="'+esc(r.name)+'">'+esc(r.name)+'</option>').join('')+'</select><label>Active <input name="active" type="checkbox" '+(x.active?'checked':'')+'></label><button class="btn btn-dark">Save</button></form>');$('#staffForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);await api('/rest/v1/profiles?id=eq.'+id,{method:'PATCH',body:JSON.stringify({full_name:f.get('name'),phone:f.get('phone'),role:f.get('role'),active:f.get('active')==='on'})});closeModal();loadStaff()}}
async function loadReport(){const from=$('#reportFrom').value||today(),to=$('#reportTo').value||today();const [b,o,e]=await Promise.all([api('/rest/v1/bookings?select=id,total,booking_date,status,payment_status&booking_date=gte.'+from+'&booking_date=lte.'+to+'&status=neq.cancelled'),api('/rest/v1/orders?select=id,total,created_at,status,payment_status&created_at=gte.'+from+'T00:00:00&created_at=lte.'+to+'T23:59:59&status=neq.cancelled'),api('/rest/v1/events?select=id,total,event_date,status&event_date=gte.'+from+'&event_date=lte.'+to+'&status=neq.cancelled')]);$('#reportBookings').textContent=b.length;$('#reportOrders').textContent=o.length;$('#reportEvents').textContent=e.length;const value=b.reduce((a,x)=>a+Number(x.total||0),0)+o.reduce((a,x)=>a+Number(x.total||0),0)+e.reduce((a,x)=>a+Number(x.total||0),0);$('#reportRevenue').textContent='UGX '+money(value);$('#reportTable').innerHTML=table(['Type','ID','Value'],[...b.map(x=>['Booking',x.id,x.total]),...o.map(x=>['Order',x.id,x.total]),...e.map(x=>['Event',x.id,x.total])],x=>x)}
async function loadSettings(){const r=await api('/rest/v1/site_settings?select=key,value&order=key.asc');const logo=r.find(x=>x.key==='logo_url');const logoInput=$('#logoUrl');if(logoInput)logoInput.value=logo?.value||'';const preview=$('#logoPreview');if(preview){const v=logo?.value||'';preview.src=v?(v.startsWith('http')?v:'../'+v.replace(/^\/+/,'')):'';preview.hidden=!v;}$('#settingsTable').innerHTML=r.filter(x=>x.key!=='logo_url').map(x=>'<label>'+esc(x.key)+'<input data-set="'+esc(x.key)+'" value="'+esc(x.value||'')+'"></label>').join('')}
async function saveSettings(){for(const x of $('[data-set]'))await api('/rest/v1/site_settings?key=eq.'+encodeURIComponent(x.dataset.set),{method:'PATCH',body:JSON.stringify({value:x.value,updated_at:new Date().toISOString()})});await loadSettings();await loadAdminLogo();alert('Site settings saved.')}
